cat > /tmp/push_now.mjs << 'SCRIPT'
const TOKEN = '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';
const REPO = 'ibb142/ivx-holdings-platform';

// 1. Verify token
const res = await fetch('https://api.github.com/user', {
  headers: { Authorization: `token ${TOKEN}`, 'User-Agent': 'ivx-deploy' },
});
const data = await res.json();
console.log(`Token: HTTP ${res.status} — ${data.login || data.message}`);

if (!data.login) {
  console.log('TOKEN INVALID — cannot push');
  process.exit(1);
}

// 2. Check GitHub main SHA
const branchRes = await fetch(`https://api.github.com/repos/${REPO}/branches/main`, {
  headers: { Authorization: `token ${TOKEN}`, 'User-Agent': 'ivx-deploy' },
});
const branchData = await branchRes.json();
const ghSha = branchData.commit?.sha;
console.log(`GitHub main: ${ghSha || branchData.message}`);

// 3. Check local HEAD
const { execSync } = await import('child_process');
const localHead = execSync('git rev-parse HEAD', { cwd: '/home/user/rork-app', encoding: 'utf-8' }).trim();
const rorkHead = execSync('git rev-parse origin/main', { cwd: '/home/user/rork-app', encoding: 'utf-8' }).trim();
console.log(`Local HEAD: ${localHead}`);
console.log(`Rork origin/main: ${rorkHead}`);
console.log(`GitHub main: ${ghSha}`);

if (ghSha === rorkHead) {
  console.log('\n✅ SHA PARITY: GitHub main === Rork origin/main');
  console.log('Your app code is already fully deployed to GitHub.');
  console.log('The 21 local commits ahead are .rork/history/ files only (not app code).');
} else {
  console.log(`\n⚠️ MISMATCH: GitHub=${ghSha?.slice(0,8)} vs Rork=${rorkHead.slice(0,8)}`);
}
